-- Row count, key sums and checksums: DWH.DIMBRANCH
-- Expected values: migration/baseline/DimBranch.csv
-- Canonicalisation: migration/validation/README.md
WITH canon AS (
    SELECT
        COALESCE(TO_VARCHAR(CAST(branchid AS NUMBER(38, 0))), CHR(30)) AS c_branchid,
        COALESCE(CAST(branchname AS VARCHAR), CHR(30)) AS c_branchname,
        COALESCE(CAST(branchlocation AS VARCHAR), CHR(30)) AS c_branchlocation,
        CAST(branchid AS NUMBER(38, 4)) AS s_branchid
    FROM dwh.dimbranch
),

hashed AS (
    SELECT
        s_branchid,
        SHA2(CONCAT_WS(CHR(31), c_branchid, c_branchname, c_branchlocation), 256) AS row_hash,
        SHA2(CONCAT_WS(CHR(31), c_branchid), 256) AS key_hash
    FROM canon
)

SELECT
    COUNT(*) AS row_count,
    COALESCE(SUM(s_branchid), 0) AS sum_branchid,
    SHA2(COALESCE(LISTAGG(row_hash, ',') WITHIN GROUP (ORDER BY row_hash), ''), 256) AS checksum
FROM hashed;
